        }
#endif
        if (!argv_set(argv, i++, arg0)) {
            argv_free(argv);
            return;
        }
        va_list args;
        va_start(args, arg0);
        const char *argn;
        while ((argn = va_arg(args, const char *)) != NULL) {
            if (!argv_set(argv, i++, argn)) {
                va_end(args);
