static int
getrandom_devurandom(void *dst, size_t bytes)
{
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        return 1;
    }

    size_t to_read = bytes;
    char *d = dst;
    while (to_read > 0) {
        ssize_t n = read(fd, d, to_read);
        if (n < 0 && (errno == EAGAIN || errno == EINTR)) {
            continue;
